"use client";

import React, { useState } from "react";
import { Check, Copy, Sparkles, ShieldCheck } from "lucide-react";

interface OtpNotificationBannerProps {
  otp: string;
  email?: string;
  sourceText?: string;
  onAutoFill?: (otp: string) => void;
  className?: string;
}

export const OtpNotificationBanner: React.FC<OtpNotificationBannerProps> = ({
  otp,
  email,
  sourceText = "Server Response OTP",
  onAutoFill,
  className = "",
}) => {
  const [copied, setCopied] = useState(false);

  if (!otp) return null;

  const handleCopy = () => {
    navigator.clipboard.writeText(otp);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div
      className={`relative overflow-hidden rounded-2xl bg-[#71AC16]/10 border-2 border-[#71AC16]/60 p-4 shadow-sm ${className}`}
    >
      <div className="flex items-start gap-3.5 relative z-10">
        <div className="w-10 h-10 rounded-xl bg-[#71AC16] text-white flex items-center justify-center flex-shrink-0 shadow-sm">
          <ShieldCheck className="w-5 h-5 font-bold" />
        </div>

        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 flex-wrap">
            <span className="text-[11px] font-black uppercase tracking-wider text-[#48720b] bg-[#71AC16]/20 px-2 py-0.5 rounded-full flex items-center gap-1">
              <Sparkles className="w-3 h-3 text-[#71AC16]" /> {sourceText}
            </span>
            {email && (
              <span className="text-[11px] text-neutral-600 truncate max-w-[200px]">
                for {email}
              </span>
            )}
          </div>

          <p className="text-xs text-neutral-700 mt-1 font-medium">
            Verification code provided by the API response:
          </p>

          <div className="mt-2.5 flex items-center gap-3 flex-wrap">
            <div className="bg-white border-2 border-[#71AC16] px-3.5 py-1.5 rounded-lg flex items-center gap-2 shadow-sm">
              <span className="font-mono text-xl font-black text-neutral-900 tracking-[0.25em]">
                {otp}
              </span>
            </div>

            <div className="flex items-center gap-2">
              {onAutoFill && (
                <button
                  type="button"
                  onClick={() => onAutoFill(otp)}
                  className="px-3.5 py-1.5 text-xs font-bold bg-[#71AC16] hover:bg-[#639912] active:scale-95 text-white rounded-lg transition-all shadow-sm flex items-center gap-1.5 cursor-pointer"
                >
                  <Sparkles className="w-3.5 h-3.5" />
                  Auto-fill Code
                </button>
              )}

              <button
                type="button"
                onClick={handleCopy}
                className="px-3 py-1.5 text-xs font-semibold bg-white hover:bg-neutral-100 active:scale-95 text-neutral-700 rounded-lg transition-all border border-neutral-300 flex items-center gap-1.5 cursor-pointer"
              >
                {copied ? (
                  <>
                    <Check className="w-3.5 h-3.5 text-[#71AC16]" />
                    <span>Copied!</span>
                  </>
                ) : (
                  <>
                    <Copy className="w-3.5 h-3.5 text-neutral-500" />
                    <span>Copy</span>
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};
