"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { authApi } from "@/lib/authApi";
import { useAuth } from "@/context/AuthContext";
import { OtpVerificationCardProps } from "./types";

export function useOtpVerification({
  email,
  initialOtp = "",
  onSuccessRedirect = "/login?registered=true",
  isForgotPasswordFlow = false,
  onForgotVerified,
  onBackToLogin,
}: Pick<
  OtpVerificationCardProps,
  | "email"
  | "initialOtp"
  | "onSuccessRedirect"
  | "isForgotPasswordFlow"
  | "onForgotVerified"
  | "onBackToLogin"
>) {
  const router = useRouter();
  const { setLatestOtpInfo, saveAuthSession } = useAuth();

  const [otp, setOtp] = useState(initialOtp);
  const [activeApiOtp, setActiveApiOtp] = useState(initialOtp);
  const [loading, setLoading] = useState(false);
  const [resending, setResending] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [cooldown, setCooldown] = useState(0);

  // Auto-fill initial OTP if provided
  useEffect(() => {
    if (initialOtp) {
      setActiveApiOtp(initialOtp);
      setOtp(initialOtp);
    }
  }, [initialOtp]);

  // Cooldown countdown timer
  useEffect(() => {
    if (cooldown > 0) {
      const timer = setTimeout(() => setCooldown((c) => c - 1), 1000);
      return () => clearTimeout(timer);
    }
  }, [cooldown]);

  const handleVerify = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setErrorMessage(null);

    const cleanOtp = otp.trim();
    if (!cleanOtp) {
      setErrorMessage("Please enter the verification code.");
      return;
    }

    try {
      setLoading(true);

      if (isForgotPasswordFlow) {
        const res = await authApi.forgotVerifyOtp(email, cleanOtp);
        if (res.data?.token) {
          setSuccessMessage("OTP verified successfully! Proceeding to set new password...");
          if (onForgotVerified) {
            onForgotVerified(res.data.token);
          }
        } else {
          setErrorMessage(res.message || "Invalid or expired OTP. Please try again.");
        }
      } else {
        // Registration/Email verification
        const res = await authApi.verifyOtp(email, cleanOtp);
        if (
          res.status === true ||
          (res as any).status === 201 ||
          (res as any).status === 200 ||
          res.message?.toLowerCase().includes("verified")
        ) {
          setLatestOtpInfo(null);

          // If the API returned a bearer token, directly save session and log in!
          if (res.token && res.data) {
            setSuccessMessage("Email verified successfully! Logging you in...");
            saveAuthSession(res.token, res.data);
            setTimeout(() => {
              router.push("/");
            }, 800);
            return;
          }

          setSuccessMessage("Account successfully verified! Redirecting to Login page...");
          setTimeout(() => {
            if (onBackToLogin) {
              onBackToLogin();
            }
            const redirectUrl = `${onSuccessRedirect}${
              onSuccessRedirect.includes("?") ? "&" : "?"
            }email=${encodeURIComponent(email)}`;
            router.push(redirectUrl);
          }, 1000);
        } else {
          setErrorMessage(res.message || "Verification failed. Please check the OTP code.");
        }
      }
    } catch (err: any) {
      setErrorMessage(err?.message || "Failed to verify OTP code.");
    } finally {
      setLoading(false);
    }
  };

  const handleResend = async () => {
    if (cooldown > 0 || resending) return;
    setErrorMessage(null);
    setSuccessMessage(null);

    try {
      setResending(true);
      const res = isForgotPasswordFlow
        ? await authApi.forgotPassword(email)
        : await authApi.resendOtp(email);

      const newOtp = res.data?.otp;
      if (newOtp) {
        setActiveApiOtp(newOtp);
        setOtp(newOtp);
        setSuccessMessage(`New OTP received: ${newOtp}`);
        setLatestOtpInfo({
          email,
          otp: newOtp,
          type: isForgotPasswordFlow ? "forgot" : "register",
        });
        setCooldown(30);
      } else {
        setErrorMessage(res.message || "Could not resend OTP. Please try again.");
      }
    } catch (err: any) {
      setErrorMessage(err?.message || "Error resending OTP.");
    } finally {
      setResending(false);
    }
  };

  return {
    otp,
    setOtp,
    activeApiOtp,
    loading,
    resending,
    errorMessage,
    successMessage,
    cooldown,
    handleVerify,
    handleResend,
  };
}
